// Some portions generated by Co-Pilot
import { fireEvent, render, screen } from "@testing-library/react";
import { renderToString } from "react-dom/server";
import { afterEach, describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import LogoCarousel from "../index";
import adopters from "@/data/adopters.json";
import * as shuffleUtils from "@/utils/shuffle";

vi.unmock("@/data/adopters.json");

afterEach(() => vi.restoreAllMocks());

describe("Adopter logo carousel", () => {
  it("uses the tight Microsoft asset with a white treatment", () => {
    render(<LogoCarousel />);
    expect(screen.getByRole("img", { name: "Microsoft" })).toHaveAttribute(
      "src",
      "/images/members/microsoft.svg",
    );
    expect(screen.getByRole("img", { name: "Microsoft" })).toHaveClass(
      "brightness-0",
      "invert",
    );
  });

  it("balances short wordmarks and stacked logos without stretching them", () => {
    render(<LogoCarousel />);
    const arm = screen.getByRole("img", { name: "Arm" });
    const michelin = screen.getByRole("img", { name: "Michelin" });
    expect(arm.parentElement).toHaveStyle({ maxWidth: "88px", height: "48px" });
    expect(michelin.parentElement).toHaveStyle({
      maxWidth: "144px",
      height: "64px",
    });
    for (const image of screen.getAllByRole("img")) {
      expect(image).toHaveClass("object-contain");
    }
  });

  it("keeps all featured adopters and their links in one carousel", () => {
    render(<LogoCarousel />);
    const featured = adopters.filter((adopter) => adopter.featured);
    expect(screen.getAllByTestId("react-slick-mock")).toHaveLength(1);
    expect(screen.getAllByRole("link")).toHaveLength(featured.length);
    for (const adopter of featured) {
      expect(screen.getByRole("link", { name: adopter.name })).toHaveAttribute(
        "href",
        adopter.url,
      );
    }
  });

  it("shuffles once per mount rather than on subsequent renders", () => {
    const shuffle = vi
      .spyOn(shuffleUtils, "shuffle")
      .mockImplementation(<T,>(items: T[]) => items.reverse());
    render(<LogoCarousel />);
    const expected = adopters
      .filter((adopter) => adopter.featured)
      .map((adopter) => adopter.name)
      .reverse();
    expect(
      screen.getAllByRole("img").map((image) => image.getAttribute("alt")),
    ).toEqual(expected);
    fireEvent.click(screen.getByRole("button"));
    expect(shuffle).toHaveBeenCalledTimes(1);
  });

  it("keeps server markup stable despite generating a random client order", () => {
    vi.spyOn(shuffleUtils, "shuffle").mockImplementation(<T,>(items: T[]) =>
      items.reverse(),
    );
    expect(renderToString(<LogoCarousel />)).toBe(
      renderToString(<LogoCarousel />),
    );
  });

  it("does not offer autoplay controls when reduced motion is requested", () => {
    vi.spyOn(window, "matchMedia").mockImplementation((query) => ({
      matches: true,
      media: query,
      onchange: null,
      addListener: vi.fn(),
      removeListener: vi.fn(),
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      dispatchEvent: vi.fn().mockReturnValue(true),
    }));
    render(<LogoCarousel />);
    expect(screen.queryByRole("button")).not.toBeInTheDocument();
  });

  it("has no accessibility violations", async () => {
    const { container } = render(<LogoCarousel />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
